    def test_non_state_snapshots_artifact_schema_variable_does_not_authorize_step_token(self) -> None:
        # Regression: schema.variables on a non-state_snapshots artifact must not be
        # harvested into direct_spec_vars; doing so would let arbitrary names bypass the
        # undefined-binding provenance check.
        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            _seed_shape_expr_schema_into(repo_root)
            _create_minimal_execution_tree(
                repo_root,
                dep_spec_id="dynamics_shallow_water_flux_2d_rusanov_p0",
                model_text="module m\nimplicit none\nend module m\n",
                runner_text="program r\nimplicit none\nend program r\n",
                run_command=["x", "y"],
                algorithm_contract={
                    "algorithm_id": "shallow_water2d_test_algorithm",
                    "execution_mode": "sequence",
                    "steps": [
                        {
                            "step_id": "compute_flux",
                            "step_kind": "flux_compute",
                            "operation_ref": "dynamics_shallow_water_flux_2d_rusanov_p0__compute_flux",
                            "inputs": ["bogus_var"],
                            "outputs": ["h", "hu", "hv"],
                        }
                    ],
                    "ordering": [],
                    "control_condition": [],
                    "iteration_contract": {"kind": "none"},
                    "update_semantics": {"mode": "in_place"},
                    "temporaries": [],
                    "derived_field_rules": [],
                    "invariants": [],
                    "splitting_policy": {"kind": "none"},
                    "state_contract": {
                        "state_variables": [
                            {"name": "h", "shape_expr": "[2,2]"},
                            {"name": "hu", "shape_expr": "[2,2]"},
                            {"name": "hv", "shape_expr": "[2,2]"},
                        ],
                        "required_update_paths": ["h", "hu", "hv"],
                        "diagnostics_from_state": True,
                        "fallback_policy": "fail_closed",
                    },
                },
                io_contract={
                    "inputs": [
                            {
                                "name": "case_resolved",
                                "source": "spec.ir.yaml",
                                "evidence_ref": "spec.ir.yaml",
                            }
                        ],
                        "outputs": [
                            {
                                "name": "metric",
                                "shape_expr": "scalar",
                                "evidence_ref": "raw/metrics_basis.json",
                                "raw_variables": ["h", "hu", "hv", "time"],
                            }
                        ],
                    "semantic_dependency": {"required_sources": []},
                    "raw_requirements": {
                        "required_evidence": [
                            # bogus_var is only declared under a non-state_snapshots
                            # artifact schema — it must NOT be harvested into
                            # direct_spec_vars and must NOT authorize step tokens.
                            {
                                "artifact": "metrics_basis.json",
                                "required": True,
                                "schema": {
                                    "variables": [{"name": "bogus_var"}],
                                },
                            },
                            {
                                "artifact": "state_snapshots",
                                "required": True,
                                "min_samples": 1,
                                "schema": {
                                    "variables": [
                                        {"name": "h", "shape_expr": "[2,2]"},
                                        {"name": "hu", "shape_expr": "[2,2]"},
                                        {"name": "hv", "shape_expr": "[2,2]"},
                                    ],
                                    "time_variable": "time",
                                    "time_shape_expr": "scalar",
                                },
                            },
                        ]
                    },
                },
            )
            violations = validate_compile_stage(
                repo_root,
                "workspace",
                "workspace/ir/problem__shallow_water2d__0.3.0/shallow-water2d_20260415_001",
            )
            self.assertTrue(
                any("bogus_var" in v and "undefined binding" in v for v in violations),
                f"expected undefined-binding violation for bogus_var; got: {violations}",
            )
            # Issue #12 item 3: the message must also name the REMEDY. Three warm retries in
            # the 2026-07-25 billed closure re-emitted the same token because the diagnosis
            # said what was wrong and not what to declare — and because `state_variables`
            # looks like a declaration, a leaf that had already declared its state there read
            # the violation as a false positive.
            offending = [v for v in violations if "bogus_var" in v and "undefined binding" in v]
            self.assertIn("algorithm.temporaries", offending[0])
            self.assertIn("algorithm.derived_field_rules", offending[0])
            self.assertIn("algorithm.state_variables does NOT", offending[0])
            # The remedy must list ALL the routes that actually clear the binding. Naming
            # only temporaries/derived_field_rules contradicted the SKILL and, for the
            # prognostic-state case the sentence itself raises, sent the leaf to the wrong
            # fix: `_extract_spec_var_names` folds the snapshot schema's variables into
            # `direct_spec_vars`, so declaring it there works and is usually what is meant.
            self.assertIn("state_snapshots schema.variables", offending[0])
            # ... and the io_contract route, which the first draft of this remedy omitted.
            # For a spec-boundary variable simply missing from io_contract.inputs, none of
            # the other three routes is the right fix, and the cheapest of them
            # (temporaries) reclassifies a spec input as an intermediate.
            self.assertIn("io_contract.inputs/outputs", offending[0])

