    def test_shape_expr_schema_load_is_lazy_and_errors_are_structured(self) -> None:
        """Regression: a missing or malformed shape_expr schema must NOT crash
        at import time (which would block `--help` and unrelated CLI flows).
        First parse-time access surfaces a `RuntimeError` whose message names
        the offending path so operators can repair it."""
        from tools.validate_pipeline_semantics import (
            _BUNDLED_SHAPE_EXPR_SCHEMA_PATH,
            _active_repo_root_for_schema,
            _load_shape_expr_patterns_cached,
            _parse_shape_expr,
        )
        with tempfile.TemporaryDirectory() as tmp:
            broken_root = Path(tmp)
            schema_dir = broken_root / "spec" / "schema" / "ir"
            schema_dir.mkdir(parents=True)
            (schema_dir / "shape_expr.schema.json").write_text(
                "{ this is not json", encoding="utf-8"
            )
            _load_shape_expr_patterns_cached.cache_clear()
            token = _active_repo_root_for_schema.set(broken_root)
            try:
                with self.assertRaises(RuntimeError) as ctx:
                    _parse_shape_expr("[3]")
                msg = str(ctx.exception)
                self.assertIn("shape_expr schema", msg)
                self.assertIn("malformed JSON", msg)
                self.assertIn(str(broken_root / "spec" / "schema" / "ir" / "shape_expr.schema.json"), msg)
            finally:
                _active_repo_root_for_schema.reset(token)
                _load_shape_expr_patterns_cached.cache_clear()
        # Bundled schema continues to work after the cache reset.
        ok, _, _ = _parse_shape_expr("[3]")
        self.assertTrue(ok)
        # Sanity: the bundled path resolution is still valid.
        self.assertTrue(_BUNDLED_SHAPE_EXPR_SCHEMA_PATH.is_file())

    def test_shape_expr_schema_resolves_from_active_repo_root(self) -> None:
        """Regression: the active repo_root's spec/schema/ir/shape_expr.schema.json
        is the canonical source — its rules apply, and missing the schema while
        a repo_root is in scope must FAIL CLOSED rather than silently falling
        back to the validator-bundled copy. Bundled fallback is reserved for
        ad-hoc / library-style invocation with no target repo in scope."""
        from tools.validate_pipeline_semantics import (
            _active_repo_root_for_schema,
            _load_shape_expr_patterns_cached,
            _parse_shape_expr,
        )
        with tempfile.TemporaryDirectory() as tmp_strict, tempfile.TemporaryDirectory() as tmp_no_schema:
            strict_root = Path(tmp_strict)
            no_schema_root = Path(tmp_no_schema)
            schema_dir = strict_root / "spec" / "schema" / "ir"
            schema_dir.mkdir(parents=True)
            strict_schema = {
                "$schema": "http://json-schema.org/draft-07/schema#",
                "oneOf": [
                    {"title": "scalar literal", "pattern": r"^[Ss][Cc][Aa][Ll][Aa][Rr]$"},
                    {
                        "title": "bracket list form (integer-only)",
                        "pattern": r"^\[\s*[0-9]+(?:\s*,\s*[0-9]+)*\s*\]$",
                    },
                ],
            }
            (schema_dir / "shape_expr.schema.json").write_text(
                json.dumps(strict_schema), encoding="utf-8"
            )

            _load_shape_expr_patterns_cached.cache_clear()
            token = _active_repo_root_for_schema.set(strict_root)
            try:
                # Identifier dim now rejected (target schema is integer-only).
                ok_id, _, _ = _parse_shape_expr("[nx]")
                self.assertFalse(ok_id, "identifier dim should be rejected by strict target schema")
                # Integer dim still passes.
                ok_int, _, _ = _parse_shape_expr("[3]")
                self.assertTrue(ok_int, "integer dim should pass strict target schema")
                # Paren tuple form not declared in strict target schema → rejected.
                ok_paren, _, _ = _parse_shape_expr("(d1, d2)")
                self.assertFalse(ok_paren, "paren form absent from strict schema should be rejected")
            finally:
                _active_repo_root_for_schema.reset(token)
                _load_shape_expr_patterns_cached.cache_clear()

            # Target with no schema while in scope must FAIL CLOSED — no silent
            # bundled fallback once a repo_root is pinned, otherwise version
            # skew between target and validator-bundle goes undetected.
            token2 = _active_repo_root_for_schema.set(no_schema_root)
            try:
                with self.assertRaises(RuntimeError) as ctx:
                    _parse_shape_expr("[3]")
                msg = str(ctx.exception)
                self.assertIn("shape_expr schema not found", msg)
                self.assertIn(
                    str(no_schema_root / "spec" / "schema" / "ir" / "shape_expr.schema.json"),
                    msg,
                )
            finally:
                _active_repo_root_for_schema.reset(token2)
                _load_shape_expr_patterns_cached.cache_clear()

            # When NO repo_root is in scope (library / ad-hoc / unit-test
            # invocation), bundled fallback IS used. This keeps test and
            # importer paths working without forcing every caller to provide
            # a target repo.
            ok_bundled, _, _ = _parse_shape_expr("[nx]")
            self.assertTrue(ok_bundled, "bundled schema applies when no repo_root is in scope")
            _load_shape_expr_patterns_cached.cache_clear()

    def test_validate_compile_stage_fails_closed_when_target_repo_lacks_schema(self) -> None:
        """Regression: public validate_*() entrypoints must bind the active
        repo_root context themselves so a target repo without
        spec/schema/ir/shape_expr.schema.json fails closed. Previously the
        context was set only by CLI main(), so library callers silently fell
        back to the validator-bundled schema, defeating the fail-closed
        protection against version skew between target and validator-bundle."""
        from tools.validate_pipeline_semantics import (
            _active_repo_root_for_schema,
            _load_shape_expr_patterns_cached,
            validate_compile_stage,
        )
        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            # Deliberately do NOT seed the schema (this test exercises the
            # missing-schema path). Build minimal plan artifacts so the
            # validator reaches shape_expr parsing.
            plan_dir = repo_root / "workspace" / "ir" / "x" / "p1"
            plan_dir.mkdir(parents=True)
            algo = {
                "algorithm_id": "alg",
                "execution_mode": "sequence",
                "steps": [],
                "ordering": [],
                "control_condition": "",
                "iteration_contract": {},
                "update_semantics": {},
                "temporaries": [{"name": "t", "shape_expr": "[3]"}],
                "derived_field_rules": [],
                "invariants": ["x"],
                "splitting_policy": {"kind": "none"},
            }
            (plan_dir / "spec.ir.yaml").write_text(
                yaml.safe_dump(algo), encoding="utf-8"
            )
            _load_shape_expr_patterns_cached.cache_clear()
            # Pre-condition: no leaked context from prior tests.
            self.assertIsNone(_active_repo_root_for_schema.get())
            # Direct library-style call must fail closed.
            with self.assertRaises(RuntimeError) as ctx:
                validate_compile_stage(repo_root, "workspace", "workspace/ir/x/p1")
            msg = str(ctx.exception)
            self.assertIn("shape_expr schema not found", msg)
            self.assertIn(
                str(repo_root / "spec" / "schema" / "ir" / "shape_expr.schema.json"),
                msg,
            )
            # Post-condition: validate_compile_stage MUST reset the context so
            # subsequent in-process calls don't see the failed repo's root.
            self.assertIsNone(
                _active_repo_root_for_schema.get(),
                "validate_compile_stage must reset the active context after returning/raising",
            )
            _load_shape_expr_patterns_cached.cache_clear()

    def test_consecutive_main_calls_do_not_leak_repo_root_context(self) -> None:
        """Regression: main() must scope `_active_repo_root_for_schema` to its
        own invocation. A long-lived process or batch tooling that invokes
        main() against repo A then repo B must NOT carry repo A's context
        into repo B's resolution. The leak is process-local and order-
        dependent, which makes it expensive to diagnose without a guard test."""
        import io
        from contextlib import redirect_stdout
        from tools.validate_pipeline_semantics import (
            _active_repo_root_for_schema,
            _load_shape_expr_patterns_cached,
            main,
        )

        def _build_repo(tmp: str) -> Path:
            repo = Path(tmp)
            sd = repo / "spec" / "schema" / "ir"
            sd.mkdir(parents=True)
            (sd / "shape_expr.schema.json").write_bytes(
                _BUNDLED_SHAPE_EXPR_SCHEMA_PATH.read_bytes()
            )
            plan_dir = repo / "workspace" / "ir" / "x" / "p1"
            plan_dir.mkdir(parents=True)
            (plan_dir / "spec.ir.yaml").write_text(
                yaml.safe_dump(
                    {
                        "algorithm_id": "a",
                        "execution_mode": "sequence",
                        "steps": [],
                        "ordering": [],
                        "control_condition": "",
                        "iteration_contract": {},
                        "update_semantics": {},
                        "temporaries": [{"name": "t", "shape_expr": "[3]"}],
                        "derived_field_rules": [],
                        "invariants": ["x"],
                        "splitting_policy": {"kind": "none"},
                    }
                ),
                encoding="utf-8",
            )
            return repo

        _load_shape_expr_patterns_cached.cache_clear()
        # Pre-condition baseline.
        baseline = _active_repo_root_for_schema.get()
        with tempfile.TemporaryDirectory() as tmp_a, tempfile.TemporaryDirectory() as tmp_b:
            repo_a = _build_repo(tmp_a)
            repo_b = _build_repo(tmp_b)
            for repo in (repo_a, repo_b):
                buf = io.StringIO()
                with redirect_stdout(buf):
                    main(
                        [
                            "--repo-root", str(repo),
                            "--stage", "compile",
                            "--ir-ref", "workspace/ir/x/p1",
                        ]
                    )
                # After each main() call the context must be reset.
                self.assertEqual(
                    _active_repo_root_for_schema.get(),
                    baseline,
                    f"main() against {repo} leaked context "
                    f"(active={_active_repo_root_for_schema.get()!r}, expected={baseline!r})",
                )

    def test_cli_emits_structured_fail_on_broken_schema(self) -> None:
        """Regression: a broken canonical schema (missing or malformed) must
        surface as `pipeline semantic validation: FAIL\\n- schema_load_failed: ...`
        on stdout rather than an uncaught traceback. Orchestration gates parse
        the structured output; an opaque crash blocks recovery and observability."""
        import io
        from contextlib import redirect_stdout
        from tools.validate_pipeline_semantics import (
            _active_repo_root_for_schema,
            _load_shape_expr_patterns_cached,
            main,
        )
        with tempfile.TemporaryDirectory() as tmp:
            broken_root = Path(tmp)
            schema_dir = broken_root / "spec" / "schema" / "ir"
            schema_dir.mkdir(parents=True)
            (schema_dir / "shape_expr.schema.json").write_text(
                "{ broken json", encoding="utf-8"
            )
            # Need a minimal ir_ref so plan-stage actually exercises shape_expr.
            ir_ref = broken_root / "workspace" / "ir" / "x" / "p1"
            ir_ref.mkdir(parents=True)
            algo = {
                "algorithm_id": "alg",
                "execution_mode": "sequence",
                "steps": [],
                "ordering": [],
                "control_condition": "",
                "iteration_contract": {},
                "update_semantics": {},
                "temporaries": [{"name": "t", "shape_expr": "[3]"}],
                "derived_field_rules": [],
                "invariants": ["x"],
                "splitting_policy": {"kind": "none"},
            }
            (ir_ref / "spec.ir.yaml").write_text(
                yaml.safe_dump(algo), encoding="utf-8"
            )
            _load_shape_expr_patterns_cached.cache_clear()
            # Reset any leaked context from earlier tests.
            try:
                prev = _active_repo_root_for_schema.get()
            except LookupError:
                prev = None
            _active_repo_root_for_schema.set(None)
            buf = io.StringIO()
            try:
                with redirect_stdout(buf):
                    rc = main([
                        "--repo-root", str(broken_root),
                        "--stage", "compile",
                        "--ir-ref", "workspace/ir/x/p1",
                    ])
            finally:
                _active_repo_root_for_schema.set(prev)
                _load_shape_expr_patterns_cached.cache_clear()
            output = buf.getvalue()
        self.assertEqual(rc, 1, f"expected exit code 1, got {rc}; output: {output!r}")
        self.assertIn("pipeline semantic validation: FAIL", output)
        self.assertIn("schema_load_failed", output)
        self.assertIn("shape_expr.schema.json", output)

    def test_shape_expr_rejects_wrapped_function_call_notation(self) -> None:
        """Regression: function-call notation must be rejected even when wrapped
        inside the bracket/paren forms (e.g. `[vector(3)]`, `[3, vector(2)]`,
        `(d1, matrix(2,2))`). The previous schema regex was permissive on
        dimension tokens; the parser now restricts each dim token to integer
        literal or identifier-style symbol.

        Single-element paren tuples like `(tensor)` and `(d1)` REMAIN valid
        because their structure is a legitimate 1-D shape — `tensor` here is
        treated as an identifier-named dimension, not a function-call."""
        from tools.validate_pipeline_semantics import _parse_shape_expr
        forbidden = [
            "[vector(3)]",
            "[matrix(3,3)]",
            "[3, vector(2)]",
            "(d1, matrix(2,2))",
            "[1+2]",
            "[3.0]",
            "[-3]",
        ]
        for expr in forbidden:
            ok, _, err = _parse_shape_expr(expr)
            self.assertFalse(ok, f"{expr!r} should be rejected, got ok=True")
            self.assertTrue(err, f"{expr!r} rejection must carry a non-empty error message")

        accepted = [
            "scalar",
            "[3]",
            "[nx, ny]",
            "(nx)",
            "(d1, d2)",
            "(tensor)",  # 1-D paren tuple with identifier-named dim — structurally valid
        ]
        for expr in accepted:
            ok, _, _ = _parse_shape_expr(expr)
            self.assertTrue(ok, f"{expr!r} should be accepted")

    def test_shape_expr_rejection_names_the_dim_token_grammar(self) -> None:
        """Issue #12 item 1: a rejected `shape_expr` must NAME the rule it broke.

        The 2026-07-25 billed E2E lost a warm retry to `[nx + 2*ng]`: the message
        listed the 3 outer forms and the function-call ban, neither of which tells
        the leaf that a dim token may not be an arithmetic expression, so the repair
        turn had to guess. Pin that the message states the per-token grammar and the
        remedy (introduce a named dimension symbol)."""
        from tools.validate_pipeline_semantics import _parse_shape_expr
        for expr in ("[nx + 2*ng]", "[n-1]", "(nx*2, ny)"):
            ok, _, err = _parse_shape_expr(expr)
            self.assertFalse(ok, f"{expr!r} should be rejected, got ok=True")
            self.assertIn("integer literal or an identifier", err, f"expr={expr!r} err={err!r}")
            self.assertIn("named dimension symbol", err, f"expr={expr!r} err={err!r}")
            # The pre-existing halves of the message must survive the extension.
            self.assertIn("shape_expr.schema.json", err)
            self.assertIn("function-call notations", err)

    def test_snapshot_provenance_does_not_depend_on_the_artifact_spelling(self) -> None:
        """`raw/state_snapshots` is a documented spelling that `_normalize_raw_evidence_artifact`
        accepts and no gate flags. `_extract_spec_var_names` used raw equality, so that spelling
        silently contributed NO provenance and every prognostic step token became an
        `undefined binding` — the false-positive class this whole change exists to remove, and
        one whose message would send the leaf to the wrong fix. Every spelling the normalizer
        accepts must yield the same provenance set."""
        from tools.validate_pipeline_semantics import _extract_spec_var_names

        def spec_vars(artifact: str) -> set[str] | None:
            doc = {
                "io_contract": {
                    "inputs": [{"name": "q_in"}],
                    "outputs": [{"name": "q_out"}],
                    "raw_requirements": {
                        "required_evidence": [
                            {
                                "artifact": artifact,
                                "schema": {
                                    "variables": [{"name": "u"}],
                                    "time_variable": "t",
                                },
                            }
                        ]
                    },
                }
            }
            with tempfile.TemporaryDirectory() as tmp:
                path = Path(tmp) / "spec.ir.yaml"
                path.write_text(yaml.safe_dump(doc), encoding="utf-8")
                return _extract_spec_var_names(path)

        canonical = spec_vars("state_snapshots")
        self.assertEqual(canonical, {"q_in", "q_out", "u"})
        for spelling in (
            "raw/state_snapshots", "State_Snapshots", "raw/state_snapshots/",
            "raw\\state_snapshots",  # the normalizer's backslash fold, otherwise unpinned
        ):
            with self.subTest(artifact=spelling):
                self.assertEqual(
                    spec_vars(spelling), canonical,
                    f"artifact spelling {spelling!r} must carry the same provenance",
                )
        # `time_variable` is deliberately NOT a provenance source — pin that the fix
        # widened the spelling only, not the set of contributing schema keys.
        self.assertNotIn("t", canonical or set())

    def test_compile_generate_skill_quotes_live_gate_messages(self) -> None:
        """The Compile.generate SKILL quotes gate messages verbatim so the leaf can
        recognize them. A quote is only useful while it matches the emitting code, and
        doc<->gate drift is this repo's recurring failure class — the size ceiling is the
        only other thing watching this file, and it would not notice a reword. Pin every
        message the SKILL quotes against the validator source."""
        repo_root = Path(vps.__file__).resolve().parent.parent
        skill = (repo_root / "skills/workflow-compile-generate/SKILL.md").read_text(
            encoding="utf-8"
        )
        source = (repo_root / "tools/validate_pipeline_semantics.py").read_text(
            encoding="utf-8"
        )
        quoted = [
            "raw_variables must be non-empty list when evidence_ref is non-snapshot "
            "and state_snapshots is required",
        ]
        for message in quoted:
            self.assertIn(message, skill, f"SKILL no longer quotes {message!r}")
            self.assertIn(
                message, source,
                f"SKILL quotes {message!r} but no validator message emits it any more",
            )
        # The other two rules this SKILL carries are paraphrases, not quotes, so they have
        # no emitter to pin against — but the doc-size ceiling is a MAXIMUM, so deleting
        # them passes every other test in the suite. Anchor them here: they are the rules
        # the 2026-07-25 warm retries broke, and the leaf can learn them nowhere else.
        for rule in (
            "unsigned integer literal or an identifier",   # the shape_expr dim-token grammar
            "is NOT one of the provenance sources",        # algorithm.state_variables
        ):
            self.assertIn(rule, skill, f"SKILL no longer states the rule {rule!r}")
        # The write contract. Same reason as the two rules above — the ceiling is a MAXIMUM, so
        # deleting the sentence passes every other test — plus one more: this SKILL is the only
        # reader of the contract that no code path checks, and its previous instruction to author
        # `algorithm.summary.md` contradicted `allowed_output_paths` for months while everything
        # stayed green.
        #
        # Pinned as a WHOLE LINE, not a substring, and this is deliberate. A substring anchor was
        # tried first and review broke it three ways while green: delete the prohibition and keep
        # the fragment; append "Also author `io_contract.yaml`"; or re-label the fragment as
        # historical and invert it ("was the OLD rule; now write whatever you need"). A rule whose
        # anchor survives its own negation is not anchored. The cost is that any reword of this
        # line fails here — the same brittleness the two rules above already carry, and the reason
        # the SKILL text is the canonical string rather than a paraphrase of it.
        # Membership of the LINE LIST, not `in skill`: a substring test still matches when the
        # rule is left intact and a contradicting clause is appended to the same bullet, which is
        # one of the three breaks review demonstrated.
        self.assertIn(
            "- **The deliverables are exactly `spec.ir.yaml` + `ir_meta.json`.** Any other file"
            " under `workspace/ir/<node_key_safe>/<ir_id>/` is outside `allowed_output_paths`,"
            " so `output_manifest_write_guard` blocks the write.",
            skill.splitlines(),
            "SKILL no longer carries the compile.generate write-contract rule verbatim",
        )
        # The retired view-only companion must not come back as an instruction under EITHER
        # spelling: the conductor does not declare it (workflow_conductor.build_launch_request)
        # and record-launch rejects it (orchestration_runtime._matches_phase_contract), so a leaf
        # told to author one is told to take a hook block. `algorithm_summary` is checked because
        # the runtime-side pin (test_orchestration_runtime) already treats the underscore form as
        # the likely re-introduction spelling — the two halves of this contract must not carry
        # different denylists, which is exactly the gap review found here.
        # A FAMILY, not a list of spellings. Round 3 walked through a two-literal denylist with
        # `algorithm-summary.md`; adding the hyphen would have invited a fourth round on the next
        # separator. Any separator (or none) between the two words is refused.
        self.assertIsNone(
            re.search(r"algorithm[-._ ]?summary", skill, re.IGNORECASE),
            "SKILL instructs an artifact the compile.generate write contract does not allow",
        )

    def test_openmp_floor_rule_is_stated_in_both_docs(self) -> None:
        """Issue #22: the reflection rule failed because only the PUNISHING side stated it.
        The fix is symmetry, and nothing else watches for its loss — both files are under a
        size ceiling, which is a MAXIMUM, so deleting either statement stays green. Anchor
        both: the `Generate.verify` SKILL must say the zero-directive slice is already
        deterministic (so the verify leaf does not re-derive a settled verdict), and
        phase_02 must document the floor beside the G6 band above it."""
        repo_root = Path(vps.__file__).resolve().parent.parent
        verify_skill = (repo_root / "skills/workflow-generate-verify/SKILL.md").read_text(
            encoding="utf-8"
        )
        phase_02 = (
            repo_root / "docs/workflow/phases/phase_02_generate.md"
        ).read_text(encoding="utf-8")
        self.assertIn(
            "enforced deterministically by the `Generate.gate` static check", verify_skill,
            "the verify SKILL no longer says the zero-`!$omp` slice is gate-settled",
        )
        self.assertIn("`!$omp` presence floor", phase_02,
                      "phase_02 no longer documents the Generate.gate presence floor")
        self.assertIn(
            "_validate_openmp_presence_floor", phase_02,
            "phase_02 no longer names the emitting checker (doc<->gate drift guard)",
        )
        # The agentic residual producer reads this SKILL instead of the pure prompt, so the
        # obligation must be stated on BOTH producer paths or the asymmetry simply moves.
        generate_skill = (
            repo_root / "skills/workflow-generate-generate/SKILL.md"
        ).read_text(encoding="utf-8")
        for rule in (
            "are **obligations**, not description",     # the knobs bind
            "Read them by MEANING, not by key name",    # the spellings vary per node
            "_validate_openmp_presence_floor",          # which slice is deterministic
            # ... and the floor's SCOPE. This was the last place stating the punishment
            # unconditionally, and it is read by exactly the agentic leaves the floor exempts.
            "The floor runs only where the `abstract` knobs affirmatively claim OpenMP as the model",
            "not on an `infrastructure`/`profile` node",
        ):
            self.assertIn(
                rule, generate_skill,
                f"the generate.generate SKILL no longer states {rule!r} — the agentic producer "
                "path would be punished by a rule only the reviewer is told (issue #22)",
            )

    def test_every_undefined_binding_line_carries_its_own_remedy(self) -> None:
        """Each violation must be self-sufficient, and the remedy must stay SHORT.

        A real IR offends in bulk — the canonical 2d example yields 17 undefined bindings.
        An earlier draft stated the full ~500-char remedy on every line (~11KB of
        near-identical text, burying the one thing that differs: which token); the next
        stated it once, on the first line. Both are wrong, and the second is worse:
        `_compile_static_inproc` excerpts the LAST 50 lines, so a remedy carried only by
        the first occurrence is precisely what a long violation list drops — leaving the
        repair turn 50 diagnoses and no fix. Keep it short and on every line."""
        from tools.validate_pipeline_semantics import _validate_algorithm_contract_file
        contract = {
            "algorithm_id": "alg_test",
            "execution_mode": "sequence",
            "steps": [
                {
                    "step_id": "s1",
                    "step_kind": "flux_compute",
                    "operation_ref": "op",
                    "inputs": ["a", "b", "c"],
                    "outputs": ["d", "e"],
                }
            ],
            "ordering": ["s1"],
            "control_condition": "",
            "iteration_contract": {},
            "update_semantics": {"target_variables": ["d"], "update_order": "sequential"},
            "temporaries": [],
            "derived_field_rules": [],
            "invariants": ["dummy"],
            "splitting_policy": {"kind": "none"},
        }
        with tempfile.TemporaryDirectory() as tmp:
            repo_root = Path(tmp)
            _seed_shape_expr_schema_into(repo_root)
            contract_path = repo_root / "spec.ir.yaml"
            contract_path.write_text(yaml.safe_dump(contract), encoding="utf-8")
            violations: list[str] = []
            _validate_algorithm_contract_file(
                repo_root,
                contract_path,
                violations,
                multidim_node_key=None,
                direct_spec_vars={"q_in"},
            )
        undefined = [v for v in violations if "undefined binding" in v]
        # Every token is still reported individually — dedup must not hide offenders.
        self.assertEqual(len(undefined), 5, undefined)
        for token in ("'a'", "'b'", "'c'", "'d'", "'e'"):
            self.assertTrue(
                any(token in v for v in undefined), f"{token} lost its own line: {undefined}"
            )
        # ... and EVERY line stands on its own: truncating to any window of these lines
        # must still hand the leaf a fix.
        for line in undefined:
            self.assertIn("io_contract.inputs/outputs", line)
            self.assertIn("algorithm.temporaries", line)
            self.assertIn("algorithm.derived_field_rules", line)
            self.assertIn("state_snapshots schema.variables", line)
            self.assertIn("algorithm.state_variables does NOT", line)
        # Budget: the sibling `validate.execute` excerpt caps at 4000 chars and
        # `_compile_static_inproc` does not cap at all, so keep the per-line cost bounded.
        # 17 such lines (the canonical 2d example) must stay well inside that budget.
        # Measured WITHOUT the leading `<contract_path>:`. That prefix is the checkout's
        # path, not something this code authors: counting it made the budget depend on
        # where the tree happens to live, and a deep enough checkout (or TMPDIR) failed
        # this test on its own, with the remedy unchanged.
        prefix = f"{contract_path}:"
        authored = []
        for line in undefined:
            self.assertTrue(line.startswith(prefix), f"no path prefix to strip: {line}")
            authored.append(line[len(prefix):])
        self.assertLess(
            max(len(v) for v in authored), 400,
            "the undefined-binding line grew past its excerpt budget; shorten the remedy "
            "and put the detail in phase_01_compile.md V3",
        )

    def test_state_variables_alone_does_not_authorize_a_step_token(self) -> None:
        """Issue #12 item 3 pins the message; this pins the DECISION the message describes.

        `allowed_tokens` deliberately excludes `algorithm.state_variables` — its own
        validation block runs only for multidimensional problem nodes, so granting
        provenance from it would authorize a field nothing has checked. Without this test
        someone could "fix" the issue-#12 false-positive complaint by adding state
        variable names to `allowed_tokens`, and the message assertion alone would still
        pass while the gate silently weakened.

        Both node-key shapes are exercised deliberately. The compile stage always passes a
        REAL `multidim_node_key` alongside `direct_spec_vars`, so a weakening written as
        "grant provenance only where the state contract IS validated" (i.e. guarded on
        `multidim_node_key`) would slip past a `None`-only fixture — which is exactly the
        reasoning the paragraph above invites."""
        from tools.validate_pipeline_semantics import _validate_algorithm_contract_file
        contract = {
            "algorithm_id": "alg_test",
            "execution_mode": "sequence",
            "steps": [
                {
                    "step_id": "s1",
                    "step_kind": "time_integrate",
                    "operation_ref": "op_step",
                    "inputs": ["u"],
                    "outputs": ["u"],
                }
            ],
            "ordering": ["s1"],
            "control_condition": "",
            "iteration_contract": {},
            "update_semantics": {"target_variables": ["u"], "update_order": "sequential"},
            # `u` is declared HERE and nowhere else — no temporaries, no derived_field_rules,
            # and not among the direct spec vars passed below.
            "state_variables": [{"name": "u", "shape_expr": "[nx]"}],
            "required_update_paths": ["u"],
            "temporaries": [],
            "derived_field_rules": [],
            "invariants": ["dummy"],
            "splitting_policy": {"kind": "none"},
        }
        for node_key in (None, "problem/shallow_water2d@0.3.0"):
            with self.subTest(multidim_node_key=node_key):
                with tempfile.TemporaryDirectory() as tmp:
                    repo_root = Path(tmp)
                    _seed_shape_expr_schema_into(repo_root)
                    contract_path = repo_root / "spec.ir.yaml"
                    contract_path.write_text(yaml.safe_dump(contract), encoding="utf-8")
                    violations: list[str] = []
                    _validate_algorithm_contract_file(
                        repo_root,
                        contract_path,
                        violations,
                        multidim_node_key=node_key,
                        direct_spec_vars={"q_in", "q_out"},
                    )
                offending = [
                    v for v in violations if "undefined binding" in v and "'u'" in v
                ]
                self.assertTrue(
                    offending,
                    f"a token declared only in algorithm.state_variables must remain an "
                    f"undefined binding; got: {violations}",
                )

    def test_parse_shape_expr_error_is_empty_exactly_when_it_succeeds(self) -> None:
        """The `temporaries` / `state_variables` guards read the REASON, not the boolean
        (`if shape_err:` rather than `if not ok:`). Those are the same test only while
        `err` is empty exactly when `ok` is True. Nothing pinned that, so a future
        rejection path returning `(False, [], "")` — the shape of the `# pragma: no cover`
        internal-parse-error return — would make both gates silently ACCEPT an invalid
        shape_expr with the whole suite still green. Pin the invariant itself."""
        from tools.validate_pipeline_semantics import _parse_shape_expr
        exprs = [
            "scalar", "SCALAR", "[3]", "[nx]", "[nx, ny]", "(nx)", "(d1, d2)", "(tensor)",
            "", "   ", "\t", "\n", "[]", "()", "[3, ]", "[a,,b]", "[nx + 2*ng]", "[n-1]",
            "[3.0]", "[-3]", "vector(3)", "matrix(3,3)", "tensor", "[vector(3)]",
            "(d1, matrix(2,2))", "[3", "3]", "scalar[3]", "[nx][ny]", "{nx}", "[nx;ny]",
            # Reaches the dim-split failure: the schema's `\s*` matches a newline but the
            # splitter's `(.+?)` does not. A folded YAML scalar produces exactly this, so
            # this is the input class that makes the invariant load-bearing rather than
            # theoretical — without it no test touches that return at all.
            "[nx,\n ny]", "(a,\nb)", "[\n nx]",
        ]
        for expr in exprs:
            ok, _, err = _parse_shape_expr(expr)
            self.assertEqual(
                ok, err == "",
                f"{expr!r}: ok={ok} but err={err!r} — the reason must be empty exactly "
                f"when the parse succeeds, or the err-based gates fail open",
            )

